     3	# CI runs the specs on the result of merging develop, so a branch that does not contain develop fails here.
     4	mkdir -p var
     5	s=0
     6	git merge-base --is-ancestor develop HEAD 2>/dev/null || { echo "FAIL base: this branch does not contain develop"; s=1; }
